var e=`1408-faapapa`;var o=`world-1408`;var t=`WS`;var i=`oceania`;var r=8;var l=52;var s={en:`Fa'apapa`,ua:`Кокосовий хліб фаапапа`};var u={en:`Fa’apapa is a dense Samoan coconut flatbread, often baked rather than yeast-risen.`,ua:`Фаапапа, щільний самоанський кокосовий хліб-корж, який зазвичай випікають без дріжджового вистоювання.`};var g=[{en:`Preheat oven to 190°C. Combine flour, baking powder, sugar and salt in a large bowl.`,ua:`Розігрійте духовку до 190°C. Змішайте в мисці борошно, розпушувач, цукор і сіль.`,t:[`mixing`],m:5,i:[[`all-purpose-flour`,420,`g`],[`baking-powder`,9,`g`],[`caster-sugar`,65,`g`],[`sea-salt`,5,`g`]]},{en:`Pour in coconut milk and stir only until a thick, slightly sticky dough forms; do not overknead.`,ua:`Влийте кокосове молоко і перемішайте до утворення густого трохи липкого тіста; не вимішуйте надмірно.`,t:[`no-knead-mixing`],m:6,i:[[`coconut-milk`,290,`ml`]]},{en:`Form a 2–3 cm thick oval or round slab on parchment. Score the top lightly to mark portions.`,ua:`Сформуйте на пергаменті овальний або круглий корж завтовшки 2–3 см. Злегка надріжте верх, позначивши порції.`,t:[`pre-shaping-dough`],m:6,i:[]},{en:`Bake for 30–35 minutes until set and lightly browned, then cool 15 minutes before slicing.`,ua:`Випікайте 30–35 хвилин до готовності й легкого рум’янцю, тоді остудіть 15 хвилин перед нарізанням.`,t:[`baking`],m:35,i:[]}];var m={slug:e,id:o,country:`WS`,region:i,servings:8,minutes:52,title:s,text:u,steps:g};export{t as country,m as default,o as id,l as minutes,i as region,r as servings,e as slug,g as steps,u as text,s as title};